// ReceptorDTO: Destinatario del documento. Los nombres de los campos no cambian entre operaciones, pero
// cuáles son obligatorios lo decide `tipoContribuyente`, y es el motivo de rechazo más
// frecuente al integrar:
//
//   - `CONTRIBUYENTE` exige `tipoContribuyenteReceptor` y `digitoVerificador`, y no lleva
//     `tipoDocumento`.
//   - `NO_CONTRIBUYENTE` exige `tipoDocumento`, y no lleva los otros dos: SIFEN rechaza
//     `tipoContribuyenteReceptor` en un no contribuyente con el código 1303.
//
// Las dos reglas van como `if`/`then` en este schema, así que un validador las detecta antes
// de mandar el request.
type ReceptorDTO struct {
	// Naturaleza del receptor (D201). Siempre se envía
	TipoContribuyente Naturaleza `json:"tipoContribuyente"`
	// Tipo de operación: B2B, B2C, B2G (organismo público) o B2F (cliente del exterior)
	TipoOperacion TipoOperacion `json:"tipoOperacion"`
	// Persona física o jurídica (D205). Obligatorio si `tipoContribuyente = CONTRIBUYENTE`; no se envía para un no contribuyente
	TipoContribuyenteReceptor TipoContribuyente `json:"tipoContribuyenteReceptor,omitempty"`
	// Tipo de documento de identidad del receptor (D208). Su descripción D209 se deriva del catálogo. Obligatorio si `tipoContribuyente = NO_CONTRIBUYENTE`; no se envía para un contribuyente
	TipoDocumento TipoDocumentoIdentidad `json:"tipoDocumento,omitempty"`
	// Descripción propia del documento de identidad (D209). Obligatoria y exclusiva de `tipoDocumento = OTRO`
	DescripcionTipoDocumento string `json:"descripcionTipoDocumento,omitempty"`
	// RUC sin el dígito verificador para un contribuyente; número de identidad (D210) para un no contribuyente. Para el receptor innominado, el literal `0`. Opcional sólo en B2F
	NumeroDocumento string `json:"numeroDocumento,omitempty"`
	// Nombre completo o razón social (D211). Para el receptor innominado, el literal `Sin Nombre`
	NombreRazonSocial string `json:"nombreRazonSocial"`
	// Dígito verificador del RUC, un solo dígito. Obligatorio si `tipoContribuyente = CONTRIBUYENTE`
	DigitoVerificador string `json:"digitoVerificador,omitempty"`
	// Nombre de fantasía del receptor (D212)
	NombreFantasia string `json:"nombreFantasia,omitempty"`
	// Domicilio del receptor (D213). Obligatorio para `tipoOperacion = B2F` y para la nota de remisión, que documenta un traslado físico; opcional en el resto. En una FE nacional exige `departamento` y `ciudad`
	Direccion string `json:"direccion,omitempty"`
	// Número de casa (D218)
	NumeroCasa *int32 `json:"numeroCasa,omitempty"`
	// Departamento del catálogo paraguayo (D219)
	Departamento string `json:"departamento,omitempty"`
	// Código de distrito del catálogo paraguayo (D221)
	CodigoDistrito *int32 `json:"codigoDistrito,omitempty"`
	// Ciudad del catálogo paraguayo (D223)
	Ciudad string `json:"ciudad,omitempty"`
	// Teléfono del receptor (D214)
	Telefono string `json:"telefono,omitempty"`
	// Teléfono móvil
	Celular string `json:"celular,omitempty"`
	// Si el envío automático está configurado, Sifende manda el KuDE a esta dirección
	Email string `json:"email,omitempty"`
	// Código interno con el que el emisor identifica al cliente (D217)
	CodigoCliente string `json:"codigoCliente,omitempty"`
	// País del receptor en código ISO. Sólo se cambia para receptores del exterior
	Pais Pais `json:"pais,omitempty"`
}

